<?php

namespace App\Support;

use Normalizer;

/**
 * PHP twin of the extension's matcher normalisation and hashing
 * (packages/matcher/src/matcher.js). Both must produce identical output;
 * tests/Unit/SpoilerHasherTest.php checks them against vectors generated by the JS code.
 */
final class SpoilerHasher
{
    /** "GTA-6's ÉNDING!" -> "gta 6 s ending" */
    public function normalize(string $text): string
    {
        $text = Normalizer::normalize($text, Normalizer::FORM_KD) ?: $text;
        $text = (string) preg_replace('/\p{M}+/u', '', $text);
        $text = mb_strtolower($text, 'UTF-8');
        $text = (string) preg_replace('/[^\p{L}\p{N}]+/u', ' ', $text);

        return trim($text);
    }

    /** "<word count>:<14 hex digits>", the format stored in rule "hashes". */
    public function hashPhrase(string $phrase, int $seed): string
    {
        $normalized = $this->normalize($phrase);
        $words = $normalized === '' ? 1 : count(explode(' ', $normalized));

        return $words.':'.str_pad(dechex($this->cyrb53($normalized, $seed)), 14, '0', STR_PAD_LEFT);
    }

    /** cyrb53 (public domain, by bryc), over UTF-16 code units like JavaScript's charCodeAt. */
    public function cyrb53(string $text, int $seed): int
    {
        $h1 = (0xDEADBEEF ^ $seed) & 0xFFFFFFFF;
        $h2 = (0x41C6CE57 ^ $seed) & 0xFFFFFFFF;

        foreach ($this->utf16Units($text) as $unit) {
            $h1 = $this->imul($h1 ^ $unit, 2654435761);
            $h2 = $this->imul($h2 ^ $unit, 1597334677);
        }

        $h1 = $this->imul($h1 ^ ($h1 >> 16), 2246822507);
        $h1 ^= $this->imul($h2 ^ ($h2 >> 13), 3266489909);
        $h2 = $this->imul($h2 ^ ($h2 >> 16), 2246822507);
        $h2 ^= $this->imul($h1 ^ ($h1 >> 13), 3266489909);

        return 4294967296 * (0x1FFFFF & $h2) + ($h1 & 0xFFFFFFFF);
    }

    /** JavaScript's Math.imul: the low 32 bits of a 32-bit multiplication, kept unsigned here. */
    private function imul(int $a, int $b): int
    {
        $a &= 0xFFFFFFFF;
        $b &= 0xFFFFFFFF;
        $high = ($a >> 16) & 0xFFFF;
        $low = $a & 0xFFFF;

        return (($low * $b) + ((($high * $b) & 0xFFFF) << 16)) & 0xFFFFFFFF;
    }

    /** @return list<int> */
    private function utf16Units(string $text): array
    {
        if ($text === '') {
            return [];
        }

        return array_values(unpack('n*', mb_convert_encoding($text, 'UTF-16BE', 'UTF-8')));
    }
}
